[
  {
    "ce_mental_state_attribution": "They probably think the line is quiet today",
    "ce_contextual_explanation": "because they were told it was closed",
    "pd_decision_conflict": "makes my stomach knot up",
    "sys_consequence_reasoning": "Nothing about it puts anybody at risk"
  },
  {
    "ce_mental_state_attribution": "must have expected a runaway someday",
    "ce_contextual_explanation": "wanted a person standing here to be able to stop it",
    "pd_decision_conflict": "My only unease is that I'm not certain",
    "sys_consequence_reasoning": "there's no one to endanger"
  },
  {
    "ce_mental_state_attribution": "might believe that members of the public touching switches",
    "ce_contextual_explanation": "given everything they've been trained on",
    "pd_decision_conflict": "My doubt is really about how much I'd actually know",
    "sys_consequence_reasoning": "I'm told no one gets endangered"
  },
  {
    "ce_mental_state_attribution": "might assume someone official is already handling it",
    "ce_contextual_explanation": "since that's what you expect at a station",
    "pd_decision_conflict": "Every second spent wondering would feel awful",
    "sys_consequence_reasoning": "lever sends the train somewhere empty and safe"
  },
  {
    "ce_mental_state_attribution": "might be counting on hearing a horn",
    "ce_contextual_explanation": "because that's how trains usually come at them",
    "pd_decision_conflict": "That thought tightens my chest",
    "sys_consequence_reasoning": "siding is empty and the barrier stops it"
  },
  {
    "ce_mental_state_attribution": "might suspect I overstepped",
    "ce_contextual_explanation": "figuring a random passenger couldn't know the whole setup",
    "pd_decision_conflict": "part of me would dread the talk afterward",
    "sys_consequence_reasoning": "nobody is put in danger by the lever"
  },
  {
    "ce_mental_state_attribution": "would likely say bystanders should never touch equipment",
    "ce_contextual_explanation": "They've presumably seen people get it wrong",
    "pd_decision_conflict": "my hands would probably shake",
    "sys_consequence_reasoning": "the siding is empty and the barrier holds"
  },
  {
    "ce_mental_state_attribution": "likely feel safe out there",
    "ce_contextual_explanation": "because they trust the schedule",
    "sys_consequence_reasoning": "There's no cost"
  },
  {
    "ce_mental_state_attribution": "Maybe they thought the brakes were set",
    "ce_contextual_explanation": "going by a routine they'd done a hundred times",
    "sys_consequence_reasoning": "the lever threatens nobody"
  },
  {
    "ce_mental_state_attribution": "they'd probably think that person just didn't care",
    "ce_contextual_explanation": "Knowing nothing about my hesitation",
    "pd_decision_conflict": "heart pounding the whole time",
    "sys_consequence_reasoning": "pulling puts no one at risk"
  }
